with q as (
 select * from (values
 ('pcac-2026-lc129-pad-instrucao-defesa-relatorio-recursos','pcac-pad-143','LC nº 129/2004 — testemunha servidora pública','Quando uma testemunha arrolada pelo acusado é servidora pública, o que prevê o parágrafo único do art. 143?','(A) A testemunha fica dispensada de comparecer.\n(B) A chefia da repartição deve ser imediatamente comunicada do mandado, com indicação do dia e hora da inquirição.\n(C) A oitiva deve ocorrer obrigatoriamente por escrito.\n(D) A comunicação deve ser feita somente depois da audiência.\n(E) A testemunha deve ser substituída por outro servidor.','B','O art. 143, parágrafo único, determina que a expedição do mandado seja imediatamente comunicada ao chefe da repartição onde a testemunha está lotada, com indicação do dia e hora da inquirição.'),
 ('pcac-2026-lc129-pad-instrucao-defesa-relatorio-recursos','pcac-pad-144-145','LC nº 129/2004 — diligências e indeferimento','Em qualquer fase do PAD, quem pode ordenar diligências de ofício ou a requerimento do acusado, e como deve agir diante de pedido manifestamente protelatório?','(A) Apenas o Delegado-Geral, sem fundamentação.\n(B) O Conselho Superior, por decisão oral.\n(C) O Presidente da Comissão; pode indeferir pedido manifestamente protelatório ou sem interesse, fundamentando a decisão.\n(D) O acusado, independentemente de autorização.\n(E) A testemunha, desde que solicite por escrito.','C','O art. 144 atribui ao Presidente da Comissão o poder de ordenar diligências em qualquer fase. O art. 145 permite indeferir requerimento manifestamente protelatório ou sem interesse para esclarecer o fato, mas exige fundamentação.'),
 ('pcac-2026-lc129-pad-instrucao-defesa-relatorio-recursos','pcac-pad-146','LC nº 129/2004 — novas imputações','Durante o PAD surge nova imputação pertinente contra o acusado. Qual providência o art. 146 exige?','(A) Incluir a imputação somente no relatório final.\n(B) Arquivar automaticamente o processo.\n(C) Intimar o acusado da nova imputação e reabrir prazo para produção de provas.\n(D) Aplicar imediatamente a penalidade.\n(E) Ouvir apenas a comissão, sem comunicar o acusado.','C','O art. 146, parágrafo único, determina que, sendo pertinente a nova arguição, o acusado seja intimado e tenha reaberto o prazo para produzir provas.'),
 ('pcac-2026-lc129-pad-instrucao-defesa-relatorio-recursos','pcac-pad-147-148','LC nº 129/2004 — defesa final e relatório','Encerrada a fase probatória, qual sequência de prazos está prevista nos arts. 147 e 148?','(A) Vista por 24 horas; defesa em 5 dias; relatório em 30 dias.\n(B) Vista por 48 horas; defesa escrita em 10 dias; relatório da comissão em 10 dias após o prazo de defesa e saneamento.\n(C) Defesa em 48 horas; relatório imediato.\n(D) Vista por 10 dias; defesa em 48 horas; relatório em 5 dias.\n(E) Defesa apenas oral, sem prazo para relatório.','B','O art. 147 prevê vista dos autos por 48 horas e prazo de 10 dias para defesa escrita. O art. 148 prevê 10 dias para a comissão apresentar o relatório após o prazo de defesa e o saneamento do processo.')
 ) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation)
)
